# Write your query here.
SELECT ?propertyType
WHERE {
    BO:exposesCommand rdf:type ?propertyType
}

# Write your query here.
SELECT ?propertyType
WHERE {
    BO:hasMetaData rdf:type ?propertyType
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property
WHERE {
    ?property rdf:type owl:ObjectProperty .
}

# Write your query here.
SELECT ?property ?meaning
WHERE {
    ?property rdf:type owl:DatatypeProperty .
    ?property rdfs:range ?meaning .
}

# Write your query here.
SELECT DISTINCT ?restrictionType
WHERE {
    ?restrictionType rdfs:subPropertyOf BO:hasDataRestriction .
    ?restrictionType rdfs:domain BO:SimpleTypeVariable .
}

# Write your query here.
SELECT ?range
WHERE {
    BO:isDataList rdfs:range ?range .
}

# Write your query here.
SELECT ?property
WHERE {
    ?property rdfs:range xsd:nonNegativeInteger .
}

